from abc import ABC, abstractmethod

class SortAlgorithm(ABC):
    @abstractmethod
    def compare(self, a, b):
        pass

    @abstractmethod
    def swap(self, array, i, j):
        pass

    def sort(self, array):
        n = len(array)
        for i in range(n):
            for j in range(0, n-i-1):
                if self.compare(array[j], array[j+1]) > 0:
                    self.swap(array, j, j+1)

class BubbleSort(SortAlgorithm):
    def compare(self, a, b):
        return a - b  # Sorts in ascending order

    def swap(self, array, i, j):
        array[i], array[j] = array[j], array[i]

class SelectionSort(SortAlgorithm):
    def compare(self, a, b):
        return a - b  # Sorts in ascending order

    def swap(self, array, i, j):
        array[i], array[j] = array[j], array[i]

# Testing
if __name__ == "__main__":
    # Sort integers
    int_array = [64, 34, 25, 12, 22, 11, 90]
    bubble_sort = BubbleSort()
    bubble_sort.sort(int_array)
    print("Bubble Sorted Integers:", int_array)

    selection_sort = SelectionSort()
    selection_sort.sort(int_array)
    print("Selection Sorted Integers:", int_array)

    # Sort strings
